const nilai: number[] = [78, 92, 65, 88];
const tertinggi = Math.max(...nilai);
const rata = nilai.reduce((a, n) => a + n, 0) / nilai.length;
console.log("Tertinggi:", tertinggi);
console.log("Rata-rata:", rata);
